"""Generated byte fixtures only. No external accounts, decoder or data required."""
from dataclasses import replace
from datetime import datetime, timedelta, timezone
import unittest

from p2_trace import Reference, Quarantine, acquisition_probe, decode

START = datetime(2020, 2, 2, 23, 50, tzinfo=timezone.utc)


def tick(seconds):
    return START + timedelta(seconds=seconds)


def point(t, h=132, meters=None):
    hr = "" if h is None else f"<HeartRateBpm><Value>{h}</Value></HeartRateBpm>"
    return (f"<Trackpoint><Time>{tick(t).isoformat()}</Time>"
            f"<DistanceMeters>{3*t if meters is None else meters}</DistanceMeters>{hr}</Trackpoint>")


def tcx(points):
    # Local clock crosses midnight relative to UTC; lap and activity encode same instant.
    return (f'<TrainingCenterDatabase xmlns="http://www.garmin.com/xmlschemas/TrainingCenterDatabase/v2">'
            f'<Activities><Activity Sport="Running"><Id>{tick(0).isoformat()}</Id>'
            f'<Lap StartTime="2020-02-03T00:50:00+01:00"><Track>{"".join(points)}</Track></Lap>'
            '</Activity></Activities></TrainingCenterDatabase>').encode()


class TraceChecks(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.raw = tcx(point(t) for t in range(1801))
        cls.trace = decode(cls.raw, "tcx")
        cls.ref = Reference(cls.trace.source_digest, "fixture-epoch", ("fixture-epoch",),
                            "calibrated_footpod", "fixture-cal", "electrical_chest_strap",
                            (tick(600), tick(700)), ((tick(0), "start"), (tick(1800), "stop")),
                            1200, "fixture-reference", True, True, 1, "fixture-route-v1", "fixture-fw")

    def test_regular_sampling_marker_quarters_and_timezone_rollover(self):
        m = acquisition_probe(self.trace, self.ref)
        self.assertEqual(self.trace.start, START)
        self.assertEqual(self.trace.points[0].meters, 0)
        self.assertEqual((m["start_offset_s"], m["distance_m"]), (600, 3600))
        self.assertEqual(m["quarter_valid_s"], (300,)*4)
        self.assertEqual(m["quarter_mean_hr_bpm"], (132,)*4)
        self.assertEqual(m["quarter_distance_m"], (900,)*4)
        self.assertEqual(m["max_observed_interval_s"], 1)
        self.assertEqual(m["status"], "PRIVATE_TRACE_QC_ONLY")

    def measure(self, transform):
        trace = decode(tcx(transform(t) for t in range(1801)), "tcx")
        return acquisition_probe(trace, replace(self.ref, source_digest=trace.source_digest))

    def test_missing_zero_not_filled(self):
        d = self.measure(lambda t: point(t, None if t == 610 else 0 if t == 620 else 132))
        self.assertEqual(d["quarter_valid_s"], (298, 300, 300, 300))

    def test_missing_hr_gap_or_poor_quarter(self):
        for label, missing, why in [
                ("gap", lambda t: 610 <= t <= 617, "hr_gap"),
                ("quarter", lambda t: 600 <= t < 900 and t % 10 == 0, "quarter_coverage"),
                ("all", lambda t: True, "hr_gap")]:
            with self.subTest(label=label), self.assertRaisesRegex(Quarantine, why):
                self.measure(lambda t: point(t, None if missing(t) else 132))

    def test_sampling_hole_or_wrong_boundary(self):
        for remove, why in [(range(611, 617), "sample_gap"), ([900], "unobserved_exact_boundary")]:
            with self.subTest(why=why), self.assertRaisesRegex(Quarantine, why):
                self.measure(lambda t: "" if t in remove else point(t))

    def test_pause_resume(self):
        def ref(stop, resume):
            return replace(self.ref, timer_events=((tick(0), "start"), (tick(stop), "stop"),
                           (tick(resume), "start"), (tick(1800), "stop")))
        with self.assertRaisesRegex(Quarantine, "paused_segment"):
            acquisition_probe(self.trace, ref(1000, 1001))
        with self.assertRaisesRegex(Quarantine, "paused_segment"):
            acquisition_probe(self.trace, ref(580, 615))
        self.assertEqual(acquisition_probe(self.trace, ref(500, 550))["duration_s"], 1200)

    def test_epoch_switch_timer_basis_missing_or_discrepant(self):
        for changes in [dict(epochs_seen=("fixture-epoch", "second")), dict(sensor="optical"),
                        dict(timer_events=()), dict(segment_timer_seconds=1197.9),
                        dict(reference_complete=False), dict(source_digest="wrong"),
                        dict(artifact_free=False), dict(marker_crossings=(tick(901),)),
                        dict(timer_events=((tick(0),"start"), (tick(5),"start"))),
                        dict(configured_interval_s=0), dict(firmware=""), dict(route_card_version="")]:
            with self.subTest(changes=changes), self.assertRaises(Quarantine):
                acquisition_probe(self.trace, replace(self.ref, **changes))

    def test_duplicate_reversed_reset_bad_hr(self):
        for a, b in [(point(0), point(0)), (point(1), point(0)),
                     (point(1), point(2, meters=0)), (point(0), point(1, h="nan"))]:
            with self.subTest(b=b), self.assertRaises(Quarantine):
                decode(tcx((a,b)), "tcx")

    def test_incomplete_corrupt_ambiguous_tcx(self):
        src = tcx((point(0), point(1)))
        for data in [src[:-12], src.replace(b"<Track>", b"<Track/><Track>"), tcx([]),
                     src.replace(b"+00:00", b""), src.replace(b"<Time>", b"<Time/><Time>"),
                     src.replace(b"<DistanceMeters>0</DistanceMeters>", b""),
                     src.replace(b"</Trackpoint>", b"<Extensions/></Trackpoint>"),
                     b"<!DOCTYPE test>" + src]:
            with self.subTest(size=len(data)), self.assertRaises(Quarantine):
                decode(data, "tcx")

    def test_multisegment_gpx_never_stitched(self):
        source = b'<gpx xmlns="http://www.topografix.com/GPX/1/1"><trk><trkseg/><trkseg/></trk></gpx>'
        with self.assertRaisesRegex(Quarantine, "ambiguous_gpx_segments"):
            decode(source, "gpx")
        with self.assertRaisesRegex(Quarantine, "unsupported_gpx_distance_and_timer"):
            decode(source.replace(b"<trkseg/><trkseg/>", b"<trkseg/>"), "gpx")

    def test_no_fit_dispatch_to_tcx(self):
        with self.assertRaisesRegex(Quarantine, "unsupported_fit_trace"):
            decode(self.raw, "fit")


if __name__ == "__main__":
    unittest.main()
